package bus

import (
	"bytes"
	"encoding/base64"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"time"
)

// Git is a thin wrapper over the system git binary operating on one clone that
// tracks the bus branch. Authentication is whatever the user's git already
// uses (ssh-agent, GIT_SSH_COMMAND, credential helper, GH_TOKEN via https...).
type Git struct {
	Dir    string // working clone
	Remote string // remote name, always "origin"
	Branch string
	Agent  string // commit author name
	// SSHKey, when set, is the private key used for this bus (generated by
	// `agentbus join`). Otherwise the user's normal git auth applies.
	SSHKey string
}

func sshCommand(key string) string {
	q := func(s string) string { return "'" + strings.ReplaceAll(s, "'", `'\''`) + "'" }
	return "ssh -i " + q(key) + " -o IdentitiesOnly=yes -o BatchMode=yes -o StrictHostKeyChecking=accept-new -o UserKnownHostsFile=" +
		q(filepath.Join(filepath.Dir(key), "known_hosts"))
}

func gitEnv(agent, sshKey string) []string {
	env := append(os.Environ(),
		"GIT_TERMINAL_PROMPT=0",
		"GIT_AUTHOR_NAME="+agent, "GIT_AUTHOR_EMAIL="+agent+"@agentbus.local",
		"GIT_COMMITTER_NAME="+agent, "GIT_COMMITTER_EMAIL="+agent+"@agentbus.local",
	)
	if sshKey != "" {
		env = append(env, "GIT_SSH_COMMAND="+sshCommand(sshKey))
	}
	// HTTPS token without putting it in the URL (CI / admin use).
	if tok := os.Getenv("AGENTBUS_GIT_TOKEN"); tok != "" {
		basic := base64.StdEncoding.EncodeToString([]byte("x-access-token:" + tok))
		env = append(env, "GIT_CONFIG_COUNT=1", "GIT_CONFIG_KEY_0=http.extraheader",
			"GIT_CONFIG_VALUE_0=AUTHORIZATION: basic "+basic)
	}
	return env
}

// LsRemote checks that remoteURL is reachable with the given key and returns
// whether branch exists there. Used by `join` to detect approval.
func LsRemote(remoteURL, branch, sshKey string) (bool, error) {
	cmd := exec.Command("git", "ls-remote", "--heads", remoteURL, branch)
	cmd.Env = gitEnv("agentbus", sshKey)
	var out, errb bytes.Buffer
	cmd.Stdout, cmd.Stderr = &out, &errb
	if err := cmd.Run(); err != nil {
		return false, fmt.Errorf("git ls-remote: %v: %s", err, Redact(strings.TrimSpace(errb.String())))
	}
	return strings.TrimSpace(out.String()) != "", nil
}

// ErrClaimLost is returned when another agent won a claim race.
var ErrClaimLost = errors.New("claim lost: another agent claimed first")

func (g *Git) run(args ...string) (string, error) {
	cmd := exec.Command("git", args...)
	cmd.Dir = g.Dir
	cmd.Env = gitEnv(g.Agent, g.SSHKey)
	var out, errb bytes.Buffer
	cmd.Stdout, cmd.Stderr = &out, &errb
	if err := cmd.Run(); err != nil {
		return out.String(), fmt.Errorf("git %s: %v: %s", strings.Join(args, " "), err, Redact(strings.TrimSpace(errb.String())))
	}
	return out.String(), nil
}

// Clone prepares dir as a clone of remoteURL on branch, creating the branch
// (orphan, with a README) when the remote does not have it yet.
func Clone(remoteURL, branch, dir, agent, sshKey string) (*Git, error) {
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return nil, err
	}
	g := &Git{Dir: dir, Remote: "origin", Branch: branch, Agent: agent, SSHKey: sshKey}
	if _, err := os.Stat(filepath.Join(dir, ".git")); err == nil {
		_, _ = g.run("remote", "set-url", "origin", remoteURL)
		if g.hasCommits() {
			return g, nil
		}
		// a previous attempt failed half-way: start over
		if err := os.RemoveAll(dir); err != nil {
			return nil, err
		}
		if err := os.MkdirAll(dir, 0o755); err != nil {
			return nil, err
		}
	}
	if _, err := g.run("init", "-q"); err != nil {
		return nil, err
	}
	if _, err := g.run("remote", "add", "origin", remoteURL); err != nil {
		return nil, err
	}
	if _, err := g.run("fetch", "-q", "origin", branch); err == nil {
		if _, err := g.run("checkout", "-q", "-B", branch, "origin/"+branch); err != nil {
			return nil, err
		}
		_, _ = g.run("branch", "-q", "--set-upstream-to=origin/"+branch)
		return g, nil
	}
	// Remote branch missing: create it.
	if _, err := g.run("checkout", "-q", "--orphan", branch); err != nil {
		return nil, err
	}
	readme := "# agentbus\n\nThis branch is an agentbus mailbox. Do not edit by hand; use the `agentbus` CLI.\n"
	if err := os.WriteFile(filepath.Join(dir, "README.md"), []byte(readme), 0o644); err != nil {
		return nil, err
	}
	if _, err := g.run("add", "README.md"); err != nil {
		return nil, err
	}
	if _, err := g.run("commit", "-q", "-m", "agentbus: init bus branch"); err != nil {
		return nil, err
	}
	if err := g.Push(); err != nil {
		// Someone else created it concurrently: adopt theirs.
		if _, ferr := g.run("fetch", "-q", "origin", branch); ferr != nil {
			return nil, err
		}
		if _, rerr := g.run("reset", "-q", "--hard", "origin/"+branch); rerr != nil {
			return nil, err
		}
	}
	return g, nil
}

// Pull fetches and rebases local unpushed commits on top. Because each agent
// only writes its own paths, the rebase cannot conflict (claims are handled
// separately by Claim).
func (g *Git) Pull() error {
	if _, err := g.run("fetch", "-q", g.Remote, g.Branch); err != nil {
		return err
	}
	if _, err := g.run("rebase", "-q", g.Remote+"/"+g.Branch); err != nil {
		_, _ = g.run("rebase", "--abort")
		return err
	}
	return nil
}

// Push pushes with bounded fetch-rebase-retry on non-fast-forward.
func (g *Git) Push() error {
	var last error
	for i := 0; i < 8; i++ {
		_, err := g.run("push", "-q", g.Remote, "HEAD:refs/heads/"+g.Branch)
		if err == nil {
			_, _ = g.run("update-ref", "refs/remotes/"+g.Remote+"/"+g.Branch, "HEAD")
			return nil
		}
		last = err
		if perr := g.Pull(); perr != nil {
			// First push of a brand new branch has nothing to pull.
			if !strings.Contains(perr.Error(), "couldn't find remote ref") {
				return perr
			}
		}
		time.Sleep(time.Duration(200*(i+1)) * time.Millisecond)
	}
	return last
}

// Ahead reports whether there are local commits not yet on the remote.
func (g *Git) Ahead() bool {
	out, err := g.run("rev-list", "--count", g.Remote+"/"+g.Branch+"..HEAD")
	if err != nil {
		return true
	}
	return strings.TrimSpace(out) != "0"
}

// Commit stages the given paths (relative to Dir) and commits. No-op when
// nothing changed.
func (g *Git) Commit(msg string, paths ...string) error {
	args := append([]string{"add", "--"}, paths...)
	if _, err := g.run(args...); err != nil {
		return err
	}
	if out, _ := g.run("diff", "--cached", "--name-only"); strings.TrimSpace(out) == "" {
		return nil
	}
	_, err := g.run("commit", "-q", "--no-verify", "-m", msg)
	return err
}

// Claim atomically creates path on the remote. The git server's
// non-fast-forward rejection is the lock: if, after a rejected push, the
// remote already holds the path, we lost.
func (g *Git) Claim(path string, content []byte, msg string) error {
	// Make sure nothing else is pending so a reset can only drop the claim.
	if g.Ahead() {
		if err := g.Push(); err != nil {
			return err
		}
	}
	if err := g.Pull(); err != nil {
		return err
	}
	abs := filepath.Join(g.Dir, path)
	if _, err := os.Stat(abs); err == nil {
		return ErrClaimLost
	}
	if err := os.MkdirAll(filepath.Dir(abs), 0o755); err != nil {
		return err
	}
	if err := os.WriteFile(abs, content, 0o644); err != nil {
		return err
	}
	if err := g.Commit(msg, path); err != nil {
		return err
	}
	for i := 0; i < 8; i++ {
		if _, err := g.run("push", "-q", g.Remote, "HEAD:refs/heads/"+g.Branch); err == nil {
			_, _ = g.run("update-ref", "refs/remotes/"+g.Remote+"/"+g.Branch, "HEAD")
			return nil
		}
		if _, err := g.run("fetch", "-q", g.Remote, g.Branch); err != nil {
			return err
		}
		if _, err := g.run("cat-file", "-e", g.Remote+"/"+g.Branch+":"+path); err == nil {
			_, _ = g.run("reset", "-q", "--hard", g.Remote+"/"+g.Branch)
			return ErrClaimLost
		}
		if _, err := g.run("rebase", "-q", g.Remote+"/"+g.Branch); err != nil {
			_, _ = g.run("rebase", "--abort")
			return err
		}
		time.Sleep(time.Duration(150*(i+1)) * time.Millisecond)
	}
	return fmt.Errorf("claim push did not converge")
}

// CommitAuthor returns the author name of the commit that added path, used to
// detect agents writing outside their own directory.
func (g *Git) CommitAuthor(path string) string {
	out, err := g.run("log", "--diff-filter=A", "--format=%an", "-1", "--", path)
	if err != nil {
		return ""
	}
	return strings.TrimSpace(out)
}

func (g *Git) hasCommits() bool {
	_, err := g.run("rev-parse", "-q", "--verify", "HEAD")
	return err == nil
}
